class Solution {
public:
    bool rotateString(string s, string goal) {
        if (s.size() != goal.size()) return false;
        string twice = s + s;
        for (int i = 0; i < (int)s.size(); i++) {
            if (twice.compare(i, goal.size(), goal) == 0) return true;
        }
        return false;
    }
};
